Alias.script:
if hq.char.inv and #hq.char.inv > 0 then
  echo("You are carrying;\n")
  for k, v in pairs(hq.char.inv) do
    echo(f" - {v}\n")
  end
  cecho(hq.prompt)  
else
  echo("You aren't carrying anything.")
  cecho(hq.prompt)
end

ScriptGroup.script:
uninstallPackage("generic_mapper")
hq = hq or {}
clearWindow() closeMapWidget()
